const p = $json.body;
const motivos = [];
const texto = x => typeof x === 'string' && x.trim().length > 0;
// Representa decimales como fracciones exactas.
const decimal = x => {
  if (typeof x !== 'number' || !Number.isFinite(x)) return null;
  const m = String(x).match(/^(-?)(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/i);
  if (!m) return null;
  let n = BigInt(m[2] + (m[3] || '')) * (m[1] ? -1n : 1n);
  let scale = (m[3] || '').length - Number(m[4] || 0);
  if (scale < 0) {
    n *= 10n ** BigInt(-scale);
    scale = 0;
  }
  return { n, d: 10n ** BigInt(scale) };
};
// Reúne los motivos de validación del pedido.
if (!p || typeof p !== 'object' || Array.isArray(p)) motivos.push('El pedido debe ser un objeto JSON');
if (!texto(p?.cliente)) motivos.push('cliente es obligatorio');
if (!texto(p?.email)) motivos.push('email es obligatorio');
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email)) motivos.push('email tiene formato inválido');
let sumN = 0n, sumD = 1n, calculable = true;
if (!Array.isArray(p?.productos) || p.productos.length === 0) {
  motivos.push('productos debe contener al menos un producto');
  calculable = false;
} else {
  p.productos.forEach((prod, i) => {
    if (!texto(prod?.nombre)) motivos.push('productos[' + i + '].nombre es obligatorio');
    const q = decimal(prod?.cantidad), price = decimal(prod?.precio);
    if (!q || q.n <= 0n) { motivos.push('productos[' + i + '].cantidad debe ser un número positivo'); calculable = false; }
    if (!price) { motivos.push('productos[' + i + '].precio es obligatorio y debe ser numérico'); calculable = false; }
    if (q && q.n > 0n && price) {
      // Acumula el importe exacto expresado en centavos.
      const n = q.n * price.n * 100n, d = q.d * price.d;
      sumN = sumN * d + n * sumD;
      sumD *= d;
    }
  });
}
// Compara el total sin redondear valores binarios.
const total = decimal(p?.total);
if (!total) motivos.push('total es obligatorio y debe ser numérico');
else if (calculable && sumN * total.d !== total.n * 100n * sumD) motivos.push('total no coincide con la suma de cantidad por precio');
return { json: { pedido: p ?? null, valido: motivos.length === 0, motivos } };
